def next_smallest_palindrome(num):
    numstr = str(num)
    length = len(numstr)

    # Generate the next palindrome based on the length
    if all(c == '9' for c in numstr):
        return 10**length + 1

    # Helper function to create a palindrome from the left half
    def create_palindrome(left, even_length):
        if even_length:
            return left + left[::-1]
        else:
            return left + left[:-1][::-1]

    # Start with the next number
    num += 1

    # Check for palindromes with the same length
    left = str(num)[:-1] if len(str(num)) % 2 == 0 else str(num)[:-2]
    while True:
        left = str(num)[:-1] if len(str(num)) % 2 == 0 else str(num)[:-2]
        pal = create_palindrome(left, len(str(num)) % 2 == 0)
        if int(pal) > num:
            return int(pal)
        num += 1
```

