def next_smallest_palindrome(num):
    numstr = str(num)
    length = len(numstr)

    # Helper function to create the smallest palindrome from a given prefix
    def create_palindrome(prefix, is_odd):
        if is_odd:
            return prefix + prefix[:-1][::-1]
        else:
            return prefix + prefix[::-1]

    # Start with the next number
    num += 1

    while True:
        s = str(num)
        if s == s[::-1]:
            return num
        # Generate potential palindromes based on the length of the current number
        if len(s) > length:
            # If length increases, the next palindrome is 10...01
            return 10**len(s) + 1
        num += 1
