def next_smallest_palindrome(num):
    numstr = str(num)
    length = len(numstr)

    # Handle the case where the number is all 9s (e.g., 99 -> 101)
    if all(c == '9' for c in numstr):
        return 10**length + 1

    # Generate the next palindrome based on the length
    half = numstr[:(length + 1) // 2]
    next_half = str(int(half) + 1)

    # Case 1: Palindrome with same length
    if len(next_half) <= (length + 1) // 2:
        if length % 2 == 0:
            candidate = half + next_half[::-1]
        else:
            candidate = half + next_half[0] + next_half[::-1]
        return int(candidate)

    # Case 2: Palindrome with increased length (e.g., 99 -> 101)
    return 10**length + 1
```

