    numstr = str(num)
    length = len(numstr)

    # Helper function to generate the next palindrome
    def generate_palindrome(s):
        if s == s[::-1]:
            return s
        # Generate the palindrome by mirroring the left half
        left = s[:len(s)//2]
        if len(s) % 2 == 0:
            return left + left[::-1]
        else:
            return left + s[len(s)//2] + left[::-1]

    # Start with the next number
    candidate = num + 1
    while True:
        s = str(candidate)
        if s == s[::-1]:
            return candidate
        # Generate the palindrome based on the length
        pal = generate_palindrome(s)
        if len(pal) > len(s):
            # If the generated palindrome is longer, return it
            return int(pal)
        candidate += 1
