def next_smallest_palindrome(num):
    numstr = str(num)
    length = len(numstr)

    # Helper function to create the next palindrome
    def create_palindrome(s, is_odd):
        if is_odd:
            return s + s[-2::-1]
        else:
            return s + s[-1::-1]

    # Check if the number is already a palindrome
    if numstr == numstr[::-1]:
        # Handle the case where the number is a palindrome
        # Increment and find the next palindrome
        num += 1
        numstr = str(num)

    # Generate the next possible palindrome
    for i in range(1, length + 1):
        prefix = numstr[:length - i]
        # Increment the prefix
        prefix = str(int(prefix) + 1)
        # Create a palindrome from the prefix
        if i % 2 == 1:
            pal = create_palindrome(prefix, True)
        else:
            pal = create_palindrome(prefix, False)
        # Check if the generated palindrome is larger than the original number
        if int(pal) > num:
            return int(pal)

    # Edge case: all 9s (e.g., 99 -> 101)
    return 10 ** length + 1
```

