def is_majority(arr, n, x):
    # Find the first occurrence of x using binary search
    left = 0
    right = n - 1
    first_occurrence = -1

    # Find the first occurrence of x
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            first_occurrence = mid
            right = mid - 1
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    if first_occurrence == -1:
        return False

    # Check if the element at first_occurrence + n//2 is also x
    if first_occurrence + n // 2 < n and arr[first_occurrence + n // 2] == x:
        return True
    else:
        return False
```

