        dp[i][1] = 1  # Only one sequence of length 1: [i]

    for length in range(2, n + 1):
        for last in range(1, m + 1):
            # Count sequences of length 'length' ending with 'last'
            # The previous element must be <= last // 2
            for prev in range(1, last // 2 + 1):
                dp[last][length] += dp[prev][length - 1]

    return sum(dp[i][n] for i in range(1, m + 1))
