    if n == 1:
        return k
    if n == 2:
        return k * (k + 1)
    mod = 1000000007
    dp_prev_prev = k  # dp[i-2]
    dp_prev = k * (k + 1)  # dp[i-1]
    for i in range(3, n + 1):
        dp_current = ((k - 1) * (dp_prev + dp_prev_prev)) % mod
        dp_prev_prev, dp_prev = dp_prev, dp_current
    return dp_prev
