import math

def sumofFactors(n):
    if n % 2 != 0:
        return 0
    res = 1
    # Check for factor 2 separately
    count = 0
    while n % 2 == 0:
        count += 1
        n = n // 2
    if count > 0:
        res *= (2**(count + 1) - 1)
    # Check for odd factors
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        count = 0
        while n % i == 0:
            count += 1
            n = n // i
        if count > 0:
            res *= (i**(count + 1) - 1) // (i - 1)
    # If remaining n is a prime > 2
    if n > 2:
        res *= (n + 1)
    return res
```

