def max_product(arr):
    n = len(arr)
    max_prod = [num for num in arr]  # Initialize max_prod with the same values as arr

    for i in range(n):
        for j in range(i + 1, n):
            # Check if the sequence is increasing
            if arr[j] < arr[j - 1]:
                break
            # Update max_prod[j] with the maximum between its current value and the product of the increasing subsequence
            max_prod[j] = max(max_prod[j], max_prod[j - 1] * arr[j])

    return max(max_prod)
```

